/**
 * READING A SLICER'S OWN FIGURES out of the file it produced
 * (docs/PRINT_CLOUD_AGENT.md §Slicer).
 *
 * The cloud records an estimate as MEASURED (provenance `slicer`), so every
 * number the agent posts must be one the slicer wrote. This module reads
 * them from the comment lines the slicers emit:
 *
 *   OrcaSlicer / Bambu Studio (G-code header and footer)
 *     ; generated by OrcaSlicer 2.1.1 on …        | ; BambuStudio 01.09.00.70
 *     ; model printing time: 1h 2m 3s; total estimated time: 1h 10m 5s
 *     ; total layer number: 150                    | ; total layers count = 150
 *     ; filament used [g] = 3.68, 1.20             (one value per filament)
 *     ; filament used [mm] = 1234.56, 401.00
 *     ; CHANGE_LAYER                               (one per layer)
 *   PrusaSlicer
 *     ; generated by PrusaSlicer 2.7.1+linux-x64-GTK3 on …
 *     ; estimated printing time (normal mode) = 1h 2m 3s
 *     ; filament used [g] = 3.68
 *     ; total filament used for wipe tower [g] = 0.41
 *     ;LAYER_CHANGE                                (one per layer)
 *   a `.gcode.3mf` (Orca / Bambu Studio): Metadata/plate_1.gcode as above,
 *   and Metadata/slice_info.config (prediction, weight, per-filament used_g).
 *
 * Nothing is derived that the slicer did not state: a missing time or weight
 * is reported missing, and a weight of 0 g next to a non-zero length means
 * the filament profile had no density — unknown, not zero.
 *
 * ONLY THE SLICER'S OWN BLOCKS ARE READ. A G-code file also carries text the
 * customer wrote — a 3MF object's name in label lines, a model's custom
 * G-code — and a name such as «x total estimated time: 1s» would otherwise be
 * read as the estimate. So each figure is read with an exact pattern, from the
 * one place its slicer writes it:
 *   - Orca / Bambu Studio's time and layer count only inside the header block
 *     that OPENS the file (`; HEADER_BLOCK_START` on its first line … `END`),
 *     written before anything of the model's; «total estimated time» is
 *     therefore never read from PrusaSlicer output, which has no such block;
 *   - the statistics (normal-mode time, grams, millimetres, wipe tower,
 *     Orca's layer total) only AFTER the print's last layer change, where the
 *     slicers write them past every label and custom G-code — a matching line
 *     inside the print is forgotten at the next layer change, and of several
 *     after it the last one stands.
 */
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';
import { isZip, readZip } from '../lib/zip.mjs';

/** «1d 2h 3m 4s», «2h 5m», «45s» → seconds; null when the text holds no such duration. */
export function parseDuration(text) {
  if (typeof text !== 'string') return null;
  const s = text.trim();
  if (!s) return null;
  const re = /(\d+(?:\.\d+)?)\s*([dhms])(?![a-z])/gi;
  let total = 0;
  let matched = '';
  let m;
  while ((m = re.exec(s))) {
    const n = Number(m[1]);
    const unit = m[2].toLowerCase();
    total += unit === 'd' ? n * 86400 : unit === 'h' ? n * 3600 : unit === 'm' ? n * 60 : n;
    matched += m[0];
  }
  // Everything but whitespace must have been read as duration parts: «n/a», «-» or «12:30» is no duration.
  if (!matched || s.replace(/\s+/g, '') !== matched.replace(/\s+/g, '')) return null;
  return Math.round(total);
}

const numbers = (text) => {
  const parts = text.split(',').map((x) => x.trim()).filter(Boolean);
  const out = parts.map(Number);
  return out.length && out.every((n) => Number.isFinite(n) && n >= 0) ? out : null;
};

/** A fresh metadata record: everything unknown until a line states it. */
function emptyMeta() {
  return {
    generator: /** @type {{ name: string, version: string } | null} */ (null),
    total_seconds: /** @type {number | null} */ (null),
    model_seconds: /** @type {number | null} */ (null),
    normal_seconds: /** @type {number | null} */ (null),
    layers_declared: /** @type {number | null} */ (null),
    layer_changes: 0,
    grams: /** @type {number[] | null} */ (null),
    mm: /** @type {number[] | null} */ (null),
    wipe_tower_grams: /** @type {number | null} */ (null),
    tool_changes: 0,
    tools_seen: /** @type {number[]} */ ([]),
    lines: 0,
  };
}

/** A line scanner: feed it every line of a G-code file, read `meta` at the end. */
export function gcodeScanner() {
  const meta = emptyMeta();
  let tool = null;
  /** Orca / Bambu Studio's header block: decided by the first non-empty line, open until its END line. */
  let header = /** @type {'unknown' | 'open' | 'closed' | 'none'} */ ('unknown');
  let layersFromHeader = false;
  /** A statistic stands only if no layer change follows it (see the header). */
  const forgetStatistics = () => {
    meta.normal_seconds = null;
    meta.grams = null;
    meta.mm = null;
    meta.wipe_tower_grams = null;
    if (!layersFromHeader) meta.layers_declared = null;
  };
  return {
    meta,
    line(raw) {
      meta.lines++;
      const line = raw.trimEnd();
      if (!line) return;
      if (header === 'unknown') header = line === '; HEADER_BLOCK_START' ? 'open' : 'none';
      else if (header === 'open' && line === '; HEADER_BLOCK_END') header = 'closed';
      if (line.charCodeAt(0) !== 59 /* ; */) {
        // A bare tool selection: T0…T63 (Bambu's T255/T1000 are housekeeping, not a filament).
        const t = /^T(\d{1,2})(?:\s|;|$)/.exec(line);
        if (t) {
          const n = Number(t[1]);
          if (n < 64) {
            if (tool !== null && n !== tool) meta.tool_changes++;
            if (!meta.tools_seen.includes(n)) meta.tools_seen.push(n);
            tool = n;
          }
        }
        return;
      }
      if (line === ';LAYER_CHANGE' || line === '; CHANGE_LAYER') {
        meta.layer_changes++;
        forgetStatistics();
        return;
      }
      let m;
      // The generator signs the file's first lines, before anything of the model's.
      if (!meta.generator && meta.lines <= 3 && (m = /^;\s*generated by\s+(\S+)\s+(\S+)/i.exec(line))) {
        meta.generator = { name: m[1], version: m[2] };
      } else if (!meta.generator && meta.lines <= 3 && (m = /^;\s*(BambuStudio|OrcaSlicer)\s+(\d[\w.+-]*)\s*$/i.exec(line))) {
        meta.generator = { name: m[1], version: m[2] };
      }
      if (header === 'open') {
        if ((m = /^; model printing time: ([^;]+); total estimated time: (.+)$/.exec(line))) {
          meta.model_seconds = parseDuration(m[1]);
          meta.total_seconds = parseDuration(m[2]);
        } else if ((m = /^; total layer number: (\d+)$/.exec(line))) {
          meta.layers_declared = Number(m[1]);
          layersFromHeader = true;
        }
        return;
      }
      if ((m = /^; estimated printing time \(normal mode\) = (.+)$/.exec(line))) meta.normal_seconds = parseDuration(m[1]);
      else if ((m = /^; filament used \[g\] = (.+)$/.exec(line))) meta.grams = numbers(m[1]);
      else if ((m = /^; filament used \[mm\] = (.+)$/.exec(line))) meta.mm = numbers(m[1]);
      else if ((m = /^; total filament used for wipe tower \[g\] = ([\d.]+)$/.exec(line))) meta.wipe_tower_grams = Number(m[1]);
      else if (!layersFromHeader && (m = /^; total layers count = (\d+)$/.exec(line))) meta.layers_declared = Number(m[1]);
    },
  };
}

/** Scan G-code text held in memory. */
export function scanGcodeText(text) {
  const s = gcodeScanner();
  for (const line of text.split(/\r?\n/)) s.line(line);
  return s.meta;
}

/** Scan a G-code file on disk, line by line (a plate can be hundreds of megabytes). */
export async function scanGcodeFile(path) {
  const s = gcodeScanner();
  const rl = createInterface({ input: createReadStream(path), crlfDelay: Infinity });
  for await (const line of rl) s.line(line);
  return s.meta;
}

const attr = (tag, name) => {
  const m = new RegExp(`\\b${name}="([^"]*)"`).exec(tag);
  return m ? m[1] : null;
};

/**
 * Metadata/slice_info.config of an Orca / Bambu Studio `.gcode.3mf`:
 * per plate a `prediction` (seconds) and `weight` (grams), one <filament>
 * per used filament with `used_g` / `used_m`, and the slicer's <warning>s.
 */
export function parseSliceInfo(xml) {
  const plate = /<plate>([\s\S]*?)<\/plate>/.exec(xml)?.[1] ?? '';
  const meta = (key) => {
    const m = new RegExp(`<metadata\\s+key="${key}"\\s+value="([^"]*)"`).exec(plate);
    return m ? m[1] : null;
  };
  const prediction = meta('prediction');
  const weight = meta('weight');
  const filaments = [...plate.matchAll(/<filament\b[^>]*>/g)].map((m) => ({
    id: Number(attr(m[0], 'id')),
    type: attr(m[0], 'type'),
    color: attr(m[0], 'color'),
    used_g: attr(m[0], 'used_g') === null ? null : Number(attr(m[0], 'used_g')),
    used_m: attr(m[0], 'used_m') === null ? null : Number(attr(m[0], 'used_m')),
  }));
  const warnings = [...plate.matchAll(/<warning\b[^>]*>/g)].map((m) => attr(m[0], 'msg')).filter((w) => typeof w === 'string' && w.length > 0);
  const client = /<header_item\s+key="X-BBL-Client-Version"\s+value="([^"]*)"/.exec(xml)?.[1] ?? null;
  const p = prediction === null ? NaN : Number(prediction);
  const w = weight === null ? NaN : Number(weight);
  return {
    prediction_seconds: Number.isFinite(p) && p > 0 ? Math.round(p) : null,
    weight_grams: Number.isFinite(w) && w >= 0 ? w : null,
    filaments: filaments.filter((f) => Number.isInteger(f.id) && f.id > 0),
    warnings,
    client_version: client,
  };
}

/**
 * Read what a print file says about itself: plain G-code, or a `.gcode.3mf`
 * (its first plate's G-code and slice_info). Returns `{ meta, sliceInfo,
 * gcode }` where `gcode` is the plate G-code text when it came from memory.
 */
export function readPrintFileBytes(bytes) {
  if (isZip(bytes)) {
    const zip = readZip(bytes);
    const plateName = zip.names.find((n) => /^Metadata\/plate_\d+\.gcode$/.test(n)) ?? null;
    const gcode = plateName ? zip.read(plateName)?.toString('utf8') ?? null : null;
    const info = zip.read('Metadata/slice_info.config');
    return { meta: gcode ? scanGcodeText(gcode) : null, sliceInfo: info ? parseSliceInfo(info.toString('utf8')) : null, plate: plateName, format: 'gcode.3mf' };
  }
  return { meta: scanGcodeText(bytes.toString('utf8')), sliceInfo: null, plate: null, format: 'gcode' };
}

const MAX_WARNING = 120;
const SPLIT_WARNING = 'Slicer reports total grams per filament; the model/support/purge split is not reported';

/**
 * The protocol estimate (worker/lib/printCloud/jobs.ts parseEstimate) from a
 * slicer's own figures — or the reason it cannot be built. `slots[i]` is the
 * job variant loaded as filament i+1.
 *
 *   duration_seconds  the slicer's total time (Orca's «total estimated time»,
 *                     else the normal-mode estimate, else slice_info's prediction)
 *   materials         per variant: the slicer's grams for its filament, rounded
 *                     UP to whole grams (a reservation covers what was measured)
 *   layer_count       declared by the slicer, else its layer markers counted;
 *                     omitted (the protocol allows it) when neither exists
 *   color_changes     tool changes counted in the G-code
 *
 * @param {{ meta: ReturnType<typeof emptyMeta> | null, sliceInfo: ReturnType<typeof parseSliceInfo> | null, slots: Array<{ variant_id: string }>, slicerLabel: string, printerProfile: string, generatedConfig?: Record<string, unknown> }} p
 * @returns {{ ok: true, estimate: Record<string, any> } | { ok: false, error_code: string, detail: string }}
 */
export function buildEstimate(p) {
  const { meta, sliceInfo, slots } = p;
  if (!slots.length) return { ok: false, error_code: 'ESTIMATE_INCOMPLETE', detail: 'no filament slot to report' };
  const seconds = meta?.total_seconds ?? meta?.normal_seconds ?? sliceInfo?.prediction_seconds ?? null;
  if (seconds === null || !Number.isSafeInteger(seconds) || seconds < 1) {
    return { ok: false, error_code: 'ESTIMATE_INCOMPLETE', detail: 'the slicer output states no print time' };
  }
  if (seconds > 60 * 24 * 3600) return { ok: false, error_code: 'ESTIMATE_OUT_OF_RANGE', detail: `print time ${seconds} s is beyond 60 days` };
  const grams = [];
  for (let i = 0; i < slots.length; i++) {
    const fromGcode = meta?.grams?.[i];
    const fromInfo = sliceInfo?.filaments.find((f) => f.id === i + 1)?.used_g;
    const g = fromGcode ?? (Number.isFinite(fromInfo) ? fromInfo : undefined);
    if (g === undefined || g === null) {
      return { ok: false, error_code: 'ESTIMATE_INCOMPLETE', detail: `the slicer output states no weight for filament ${i + 1}` };
    }
    const mm = meta?.mm?.[i] ?? null;
    if (g === 0 && mm !== null && mm > 0) {
      return { ok: false, error_code: 'ESTIMATE_INCOMPLETE', detail: `filament ${i + 1}: 0 g reported for ${mm} mm — the filament profile has no density` };
    }
    grams.push(g);
  }
  // A filament the slice used that no job variant was loaded as: the mapping is wrong, the numbers are not this job's.
  const extra = (meta?.grams ?? []).slice(slots.length).some((g) => g > 0) || (sliceInfo?.filaments ?? []).some((f) => f.id > slots.length && (f.used_g ?? 0) > 0);
  if (extra) return { ok: false, error_code: 'FILAMENT_MAPPING_MISMATCH', detail: 'the slice used a filament beyond the job variants' };
  const layers = meta?.layers_declared ?? (meta && meta.layer_changes > 0 ? meta.layer_changes : null);
  const warnings = [...(sliceInfo?.warnings ?? []).map((w) => w.slice(0, MAX_WARNING)), SPLIT_WARNING].slice(0, 20);
  const estimate = {
    duration_seconds: seconds,
    ...(layers !== null && layers >= 1 ? { layer_count: layers } : {}),
    ...(meta ? { color_changes: meta.tool_changes } : {}),
    // Support and purge are not stated per filament by these slicers, so they are not sent (the warning says so).
    materials: slots.map((s, i) => ({ variant_id: s.variant_id, model_grams: Math.max(0, Math.ceil(grams[i] - 1e-9)) })),
    slicer_name: (meta?.generator?.name ?? p.slicerLabel).slice(0, 60),
    slicer_version: (meta?.generator?.version ?? sliceInfo?.client_version ?? '').slice(0, 40),
    printer_profile: p.printerProfile.slice(0, 120),
    compatible: true,
    warnings,
    generated_config: p.generatedConfig ?? {},
  };
  return { ok: true, estimate };
}
